/** Typed shape of results/web_dashboard_data.json (generated by main.py). */

export interface PolicyRow {
  policy: string;
  total_energy_kwh: number;
  total_it_kwh_incl_switch: number;
  pue_avg: number;
  arrived_tasks: number;
  served_tasks: number;
  dropped_tasks: number;
  sla_violation_rate_pct: number;
  drop_events: number;
  hot_steps: number;
  hot_frac_pct: number;
  warm_frac_pct: number;
  cool_frac_pct: number;
  switch_count: number;
  avg_queue: number;
  max_queue: number;
  total_reward: number;
  energy_saved_vs_always_on_pct: number;
}

export interface Trace {
  hours: number[];
  lam: number[];
  u: number[][]; // [cluster][bin] values 0..3
  q: number[];
  tau: number[];
  energy_kwh: number[];
  dropped: number[];
  arrived: number[];
}

export interface ParetoPoint {
  label: string;
  penalty_drop?: number;
  energy_kwh: number;
  sla_violation_rate_pct: number;
  kind: "dp-sweep" | "dp-main" | "baseline";
  guardrail_ok?: boolean;
  marker?: string;
  color?: string;
}

export interface DecisionSlice {
  u: number[];
  title: string;
  grid: number[][]; // [tau][q] -> class index
  cooling: number[][]; // 0 low, 1 high
}

export interface AdpPayload {
  n_clusters: number;
  tabular_state_space: number;
  tabular_sparse_entries: number;
  theta: number[];
  feature_names: string[];
  td_curve: number[];
  n_steps: number;
  time_s: number;
  traces: Record<string, Trace>;
  metrics: Record<string, PolicyRow>;
}

export interface DashboardData {
  meta: {
    generated_utc: string;
    python: string;
    numpy: string;
    seed: number;
    timings: Record<string, number>;
    runtime_source: string;
    surge_floor_tasks: number;
    offered_tasks: number;
  };
  spec: {
    n_clusters: number;
    q_max: number;
    n_states: number;
    n_actions: number;
    gamma: number;
    lambda_solve: number;
    step_minutes: number;
    peak_kw: number[];
    cap_table: number[][];
    power_frac: number[];
    pue_table: number[][];
    e_switch_kwh: number[];
    w_energy: number;
    w_switch: number;
    w_sla: number;
    penalty_drop: number;
    penalty_hot: number;
    u_labels: string[];
    tau_labels: string[];
  };
  validation: Record<string, number>;
  regimes: { lambdas: number[]; cuts: number[]; rtdp_lambda: number };
  diurnal: { hours: number[]; lam: number[]; hourly_anchors: number[] };
  convergence: {
    vi_sync: { residuals: number[]; n_sweeps: number; time_s: number; theta: number; converged: boolean };
    vi_gs: { residuals: number[]; n_sweeps: number; time_s: number; theta: number; converged: boolean };
    pi: {
      policy_changes: number[];
      eval_residuals: number[];
      n_iters: number;
      time_s: number;
      oscillation_detected: boolean;
    };
    rtdp: {
      curve: number[];
      n_trials: number;
      visited_states: number;
      time_s: number;
      max_gap_vs_vi_on_visited: number;
      max_gap_on_frequent_states: number;
      policy_agreement_on_visited_pct: number;
    };
    agreement: { max_v_diff_worst_regime: number; policy_agreement_worst_regime_pct: number };
  };
  pareto: { points: ParetoPoint[]; guardrail_min_w3_times_drop: number };
  policies: PolicyRow[];
  traces: Record<string, Trace>;
  decision_boundary: { class_names: string[]; slices: DecisionSlice[] };
  adp: AdpPayload | null;
}
